"<label>Földrajzi hosszúság (°)<input id=\"longitude\" type=\"number\" min=\"-180\" max=\"180\" step=\"any\" placeholder=\"19.0402\" required></label></div>\n"
"<small>Időjárási adatok: <a href=\"https://open-meteo.com/\" rel=\"noopener noreferrer\" target=\"_blank\">Open-Meteo</a> · <a href=\"https://creativecommons.org/licenses/by/4.0/\" rel=\"noopener noreferrer\" target=\"_blank\">CC BY 4.0</a>. Az ingyenes végpont személyes, nem kereskedelmi használatra érhető el.</small></section>\n"
"<button type=\"submit\" id=\"save-inverter\" disabled>Inverter és időprogramok mentése</button>\n"
"</fieldset><p id=\"result\" role=\"status\" aria-live=\"polite\"></p></form>\n"
"<script>/* A párosított kijelzők szerkesztése. A 202 csak átvétel; a tartós mentést\n"
" * a külön visszaolvasott saved_revision igazolja. A draft nem veszhet el. */\n"
"const LoxoneSlaves = (() => {\n"
"    'use strict';\n"
"    const get = id => document.getElementById(id);\n"
"    const inverter = !!get('inverter-form');\n"
"    const url = inverter ? '/api/inverter/slaves' : '/api/loxone/slaves';\n"
"    const requestHeader = inverter ? 'X-Zolee-Inverter' : 'X-Zolee-Loxone';\n"
"    const rows = new Map();\n"
"    const keys = inverter ? ['name', 'rotation_degrees', 'day_brightness', 'night_brightness'] : ['name', 'presence_uuid', 'timeout_seconds', 'blank_at_day', 'blank_at_night',\n"
"        'rotation_degrees', 'day_brightness', 'night_brightness'];\n"
"    const rotations = [['0', 'Álló (0°)'], ['90', 'Elforgatva 90°-kal'],\n"
"        ['180', 'Fejjel lefelé (180°)'], ['270', 'Elforgatva 270°-kal']];\n"
"    const brightnessKeys = ['day_brightness', 'night_brightness'];\n"
"    const profile = value => Object.fromEntries(keys.map(key => [key,\n"
"        key === 'blank_at_day' ? (value[key] ?\? false) :\n"
"        brightnessKeys.includes(key) && value[key] == null ? null : value[key]]));\n"
"    const same = (a, b) => keys.every(key => key === 'blank_at_day' ?\n"
"        (a[key] ?\? false) === (b[key] ?\? false) : a[key] === b[key]);\n"
"    let catalog = [], catalogKey = '', state = null, fetching = null;\n"
"    let online = false, writing = null, otherBusy = false;\n"
"\n"
"    function create(tag, text) {\n"
"        const node = document.createElement(tag);\n"
"        if (text !== undefined) node.textContent = text;\n"
"        return node;\n"
"    }\n"
"    function tell(node, text, error = false) {\n"
"        node.textContent = text;\n"
"        node.className = error ? 'feedback-error' : '';\n"
"    }\n"
"    function controls() {\n"
"        for (const row of rows.values()) {\n"
"            const locked = writing === row || (row.pending && !state?.save_error);\n"
"            for (const input of Object.values(row.inputs)) input.disabled = !!locked;\n"
"            row.save.disabled = !online || !state?.enabled || !state?.ready ||\n"
"                otherBusy || !!writing || !!locked || !row.dirty || !row.present;\n"
"            row.discard.disabled = !!locked || !online || !row.present;\n"
"        }\n"
"    }\n"
"    function choices(row) {\n"
"        if (inverter) return;\n"
"        const select = row.inputs.presence_uuid, selected = row.draft.presence_uuid;\n"
"        const room = get('slave-room').value, category = get('slave-category').value;\n"
"        select.replaceChildren();\n"
"        const add = (value, text) => {\n"
"            const option = create('option', text);\n"
"            option.value = value;\n"
"            select.append(option);\n"
"        };\n"
"        add('', 'Csak érintéses ébresztés');\n"
"        const seen = new Set();\n"
"        for (const item of catalog) {\n"
"            if (!item.uuid || seen.has(item.uuid)) continue;\n"
"            if (item.uuid !== selected && ((room && JSON.stringify(item.room || '') !== room) ||\n"
"                (category && JSON.stringify(item.category || '') !== category))) continue;\n"
"            seen.add(item.uuid);\n"
"            add(item.uuid, (item.name || 'Névtelen') + ' (' + (item.room || '–') + ' / ' +\n"
"                (item.category || '–') + ') · ' + (item.state || 'állapot'));\n"
"        }\n"
"        if (selected && !seen.has(selected)) add(selected, 'Korábban párosított / nem található: ' + selected);\n"
"        select.value = selected;\n"
"    }\n"
"    function filters() {\n"
"        if (inverter) return;\n"
"        for (const [id, key, title] of [['slave-room', 'room', 'Összes helyiség'],\n"
"            ['slave-category', 'category', 'Összes funkció']]) {\n"
"            const select = get(id), selected = select.value;\n"
"            select.replaceChildren();\n"
"            const values = [...new Set(catalog.map(item => item[key] || ''))].sort((a, b) => a.localeCompare(b, 'hu'));\n"
"            for (const [value, text] of [['', title], ...values.map(value => [JSON.stringify(value), value || 'Nincs megadva'])]) {\n"
"                const option = create('option', text);\n"
"                option.value = value;\n"
"                select.append(option);\n"
"            }\n"
"            select.value = values.some(value => JSON.stringify(value) === selected) ? selected : '';\n"
"        }\n"
"        for (const row of rows.values()) choices(row);\n"
"    }\n"
"    function load(row, value) {\n"
"        row.base = profile(value);\n"
"        row.draft = profile(value);\n"
"        row.dirty = false;\n"
"        row.pending = null;\n"
"        for (const key of keys) {\n"
"            const input = row.inputs[key];\n"
"            if (key === 'blank_at_day' || key === 'blank_at_night') input.checked = !!row.draft[key];\n"
"            else input.value = value[key] == null ? '' : String(value[key]);\n"
"        }\n"
"        row.legend.textContent = value.name;\n"
"        choices(row);\n"
"    }\n"
"    function make(value) {\n"
"        const row = {id: value.id, inputs: {}, dirty: false, pending: null, present: true};\n"
"        row.box = create('fieldset');\n"
"        row.legend = create('legend', value.name);\n"
"        row.box.append(row.legend);\n"
"        row.box.append(create('small', 'Eszköz: ' + value.id));\n"
"        const grid = create('div');\n"
"        grid.className = 'grid';\n"
"        for (const [key, title, type] of [['name', 'Eszköz neve', 'text'],\n"
"            ['presence_uuid', 'Loxone jelenlétállapot', 'select'],\n"
"            ['timeout_seconds', 'Sötétítési késleltetés (másodperc)', 'number'],\n"
"            ['blank_at_day', 'Sötétítés nappal, ha nincs jelenlét', 'checkbox'],\n"
"            ['blank_at_night', 'Sötétítés éjszaka, ha nincs jelenlét', 'checkbox'],\n"
"            ['rotation_degrees', 'Kijelző elforgatása (a Slave újraindul)', 'rotation'],\n"
"            ['day_brightness', 'Nappali fényerő (%)', 'brightness'],\n"
"            ['night_brightness', 'Éjszakai fényerő (%)', 'brightness']]) {\n"
"            if (!keys.includes(key)) continue;\n"
"            const list = type === 'select' || type === 'rotation';\n"
"            const label = create('label', title), input = create(list ? 'select' : 'input');\n"
"            input.id = 'slave-' + value.id + '-' + key;\n"
"            if (!list) input.type = type === 'brightness' ? 'number' : type;\n"
"            if (type === 'text') input.maxLength = 80;\n"
"            if (type === 'number') { input.min = 1; input.max = 86400; input.step = 1; }\n"
"            if (type === 'brightness') {\n"
"                input.min = 1; input.max = 100; input.step = 1;\n"
"                input.placeholder = 'Master értéke';\n"
"            }\n"
"            if (type === 'rotation') for (const [option, text] of rotations) {\n"
"                const node = create('option', text);\n"
"                node.value = option;\n"
"                input.append(node);\n"
"            }\n"
"            input.oninput = input.onchange = () => {\n"
"                const current = state?.profiles.find(value => value.id === row.id);\n"
"                if (row.pending && current && same(current, row.pending)) row.base = profile(current);\n"
"                row.draft[key] = type === 'checkbox' ? input.checked :\n"
"                    type === 'rotation' ? Number(input.value) : type === 'brightness' ?\n"
"                    (input.value.trim() ? Number(input.value) : null) : type === 'number' ?\n"
"                    (input.value.trim() ? Number(input.value) : NaN) : input.value;\n"
"                row.pending = null;\n"
"                row.dirty = !same(row.base, row.draft);\n"
"                tell(row.status, row.dirty ? 'Még nincs elmentve.' : 'Nincs módosítás.');\n"
"                controls();\n"
"            };\n"
"            row.inputs[key] = input;\n"
"            label.append(input);\n"
"            grid.append(label);\n"
"        }\n"
"        row.box.append(grid);\n"
"        row.save = create('button', 'Eszköz beállításainak mentése');\n"
"        row.discard = create('button', 'Szerkesztés elvetése');\n"
"        row.save.id = 'slave-' + value.id + '-save';\n"
"        row.discard.id = 'slave-' + value.id + '-discard';\n"
"        row.save.type = row.discard.type = 'button';\n"
"        row.save.onclick = () => save(row);\n"
"        row.discard.onclick = () => {\n"
"            if (row.discard.disabled) return;\n"
"            const current = state.profiles.find(item => item.id === row.id);\n"
"            if (current) { load(row, current); tell(row.status, 'Az eszközről beolvasott beállítások.'); controls(); }\n"
"        };\n"
"        row.status = create('p');\n"
"        row.status.id = 'slave-' + value.id + '-status';\n"
"        row.status.setAttribute('role', 'status');\n"
"        row.status.setAttribute('aria-live', 'polite');\n"
"        row.box.append(row.save);\n"
"        row.box.append(row.discard);\n"
"        row.box.append(row.status);\n"
"        rows.set(row.id, row);\n"
"        get('slave-profiles').append(row.box);\n"
"        load(row, value);\n"
"        return row;\n"
"    }\n"
"    function apply(next) {\n"
"        if (next.schema !== 1 || !Array.isArray(next.profiles)) throw Error('Ismeretlen eszközlista.');\n"
"        state = next;\n"
"        online = true;\n"
"        for (const row of rows.values()) row.present = false;\n"
"        for (const value of next.profiles) {\n"
"            const row = rows.get(value.id) || make(value);\n"
"            row.present = true;\n"
"            if (row.pending) {\n"
"                if (!same(value, row.pending)) {\n"
"                    row.pending = null;\n"
"                    tell(row.status, same(value, row.base) ?\n"
"                        'A mentés nem igazolt; az eszköz még a korábbi beállítást mutatja. Újrapróbálhatod.' :\n"
"                        'A profil közben másik helyen változott. Ellenőrizd, vagy vesd el a szerkesztést.', true);\n"
"                } else if (next.save_error) {\n"
"                    tell(row.status, 'A tartós mentés sikertelen. A beállítás még nincs biztonságban; újrapróbálhatod a mentést.', true);\n"
"                } else if (next.saved_revision === next.revision) {\n"
"                    load(row, value);\n"
"                    tell(row.status, 'Beállítások tartósan elmentve.');\n"
"                } else tell(row.status, 'Beállítások átvéve, tartós mentés folyamatban…');\n"
"            } else if (!row.dirty) {\n"
"                load(row, value);\n"
"                tell(row.status, next.save_error ? 'A Master tartós mentése hibát jelzett.' :\n"
"                    next.saved_revision !== next.revision ? 'Tartós mentés folyamatban…' :\n"
"                    'Beállítások tartósan elmentve.', !!next.save_error);\n"
"            }\n"
"            else if (!same(value, row.base)) tell(row.status,\n"
"                'A profil közben másik helyen változott. A saját szerkesztésed megmaradt; ellenőrizd, vagy vesd el.', true);\n"
"        }\n"
"        for (const row of rows.values()) if (!row.present) tell(row.status,\n"
"            'Az eszköz most nem érhető el a listában. A szerkesztésed megmaradt.', true);\n"
"        let text = !next.enabled ? 'Kapcsold be a Master adat seed funkcióját a Beállítások oldalon.' :\n"
"            !next.ready ? 'A Slave-szolgáltatás nem érhető el. Ellenőrizd az eszközt.' :\n"
"            !next.profiles.length ? 'Még nincs párosított Slave-kijelző. Indítsd a párosítást a Master diagnosztikai oldalán, a PIN-kóddal.' :\n"
"            next.save_error ? 'A tartós mentés hibát jelzett. A Master újrapróbálja; az eszközbeállításoknál is újraindíthatod a mentést.' :\n"
"            next.saved_revision !== next.revision ? 'Tartós mentés folyamatban…' : 'A kijelzők beállításai tartósan mentve.';\n"
"        tell(get('slave-status'), text, next.enabled && (!next.ready || !!next.save_error));\n"
"        controls();\n"
"    }\n"
"    async function read() {\n"
"        if (fetching) return fetching;\n"
"        fetching = (async () => {\n"
"            try {\n"
"                const response = await apiFetch(url, {cache: 'no-store'});\n"
"                if (!response.ok) throw Error(await response.text());\n"
"                apply(await response.json());\n"
"                return true;\n"
"            } catch (error) {\n"
"                online = false;\n"
"                tell(get('slave-status'), 'Az eszközlista nem frissíthető. A szerkesztésed megmaradt. ' + error.message, true);\n"
"                controls();\n"
"                return false;\n"
"            }\n"
"        })();\n"
"        try { return await fetching; } finally { fetching = null; }\n"
"    }\n"
"    function validate(value) {\n"
"        if (!value.name || new TextEncoder().encode(value.name).length > 80 ||\n"
"            ![...value.name].some(char => ![' ', '\\u00a0'].includes(char)) ||\n"
"            [...value.name].some(char => { const code = char.codePointAt(0); return code < 32 ||\n"
"                (code >= 127 && code <= 159) || (code >= 0xd800 && code <= 0xdfff); }))\n"
"            return 'Adj meg olvasható, legfeljebb 80 bájtos nevet (az ékezetes betűk több helyet foglalnak).';\n"
"        if (!inverter && (!Number.isInteger(value.timeout_seconds) || value.timeout_seconds < 1 || value.timeout_seconds > 86400))\n"
"            return 'A sötétítési késleltetés 1 és 86400 közötti egész másodperc legyen.';\n"
"        if (value.presence_uuid && !/^[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{16}$/.test(value.presence_uuid))\n"
"            return 'Válassz érvényes Loxone jelenlétállapotot.';\n"
"        if (![0, 90, 180, 270].includes(value.rotation_degrees))\n"
"            return 'A kijelző elforgatása 0, 90, 180 vagy 270 fok lehet.';\n"
"        for (const key of brightnessKeys) {\n"
"            if (value[key] !== null &&\n"
"                (!Number.isInteger(value[key]) || value[key] < 1 || value[key] > 100))\n"
"                return 'A nappali és éjszakai fényerő 1–100 közötti egész százalék legyen, vagy maradjon üres.';\n"
"        }\n"
"        return '';\n"
"    }\n"
"    async function save(row) {\n"
"        if (row.save.disabled) return;\n"
"        const desired = profile(row.draft), error = validate(desired);\n"
"        if (error) { tell(row.status, error, true); return; }\n"
"        writing = row;\n"
"        controls();\n"
"        try {\n"
"            if (!await read() || !state.enabled || !state.ready) return;\n"
"            const current = state.profiles.find(value => value.id === row.id);\n"
"            if (!current || (!same(current, row.base) && !(row.pending && same(current, row.pending)))) {\n"
"                tell(row.status, 'A profil közben változott. Vesd el a szerkesztést, majd ellenőrizd az új beállításokat.', true);\n"
"                return;\n"
"            }\n"
"            let response;\n"
"            try {\n"
"                response = await apiFetch(url, {method: 'POST',\n"
"                    headers: {'Content-Type': 'application/json', [requestHeader]: '1'},\n"
"                    body: JSON.stringify({schema: 1, revision: state.revision, id: row.id, profile: desired})});\n"
"            } catch (error) {\n"
"                /* A válasz elveszhetett a kérés átvétele után. Csak visszaolvasunk. */\n"
"                row.pending = desired;\n"
"                if (await read()) return;\n"
"                throw error;\n"
"            }\n"
"            if (!response.ok) throw Error(await response.text());\n"
"            row.pending = desired;\n"
"            tell(row.status, 'Beállítások átvéve, tartós mentés folyamatban…');\n"
"            await read();\n"
"        } catch (error) {\n"
"            /* Elveszett válasznál nincs automatikus újraküldés vagy sikerállítás. */\n"
"            tell(row.status, 'A mentés nem igazolt. Ellenőrizd a friss állapotot, majd próbáld újra. ' + error.message, true);\n"
"        } finally {\n"
"            writing = null;\n"
"            controls();\n"
"        }\n"
"    }\n"
"    async function refresh(nextCatalog = [], busy = false) {\n"
"        otherBusy = busy;\n"
"        const key = JSON.stringify(nextCatalog);\n"
"        if (key !== catalogKey) { catalogKey = key; catalog = nextCatalog; filters(); }\n"
"        controls();\n"
"        if (!writing) await read();\n"
"        return state?.profiles || [];\n"
"    }\n"
"    if (!inverter) for (const id of ['slave-room', 'slave-category']) get(id).onchange = () => {\n"
"        for (const row of rows.values()) choices(row);\n"
"    };\n"
"    filters();\n"
"    return {refresh};\n"
"})();\n"
"</script><script>/* Az adatokat a firmware gyári regisztertérképe adja. Csak a kiválasztott\n"
" * profil eltérései kerülnek a mentésbe. A többi vázlat a böngészőben marad. */\n"
"const inverterRegisters = (() => {\n"
"    const drafts = new Map();\n"
"    let generation = 0, selected = '', rows = [], ready = false;\n"
"\n"
"    function savedOverrides() {\n"
"        return saved?.profile === selected ? (saved.registerOverrides || {}) : {};\n"
"    }\n"
"    function applicable(spec) {\n"
"        if (selected !== 'solax_modbus') return true;\n"
"        const model = get('device')?.value || '';\n"
"        if (spec.id.startsWith('x1_')) return model === 'X1-G4';\n"
"        if (spec.id.startsWith('x3_')) return model !== 'X1-G4';\n"
"        return !spec.id.startsWith('pro_') || model === 'X3-G4-PRO';\n"
"    }\n"
"    function status() {\n"
"        const defaults = savedOverrides();\n"
"        let edited = 0;\n"
"        for (const {spec, input, restore, box} of rows) {\n"
"            box.hidden = input.disabled = !applicable(spec);\n"
"            if (box.hidden) continue;\n"
"            const value = input.valueAsNumber;\n"
"            restore.disabled = value === spec.address;\n"
"            if (value !== (defaults[spec.id] ?\? spec.address)) ++edited;\n"
"        }\n"
"        get('register-status').textContent = edited ? 'Nem mentett regisztercímek: ' + edited + '.' : '';\n"
"    }\n"
"    function row(spec, draft) {\n"
"        const box = el('div'), description = el('div'), label = el('label', spec.label);\n"
"        const input = el('input'), restore = el('button', 'Gyári cím visszaállítása');\n"
"        box.className = 'register-row';\n"
"        input.id = 'register-' + spec.id;\n"
"        label.htmlFor = input.id;\n"
"        input.type = 'number'; input.min = '0'; input.max = String(65536 - spec.words);\n"
"        input.step = '1'; input.required = true; input.inputMode = 'numeric';\n"
"        input.value = draft.has(spec.id) ? draft.get(spec.id) : spec.address;\n"
"        const info = el('small', (spec.base ? 'Gyári eltolás: ' : 'Gyári cím: ') + spec.address +\n"
"            ' · FC' + String(spec.function).padStart(2, '0') + ' · ' + spec.words + ' szó' +\n"
"            (spec.format ? ' · ' + spec.format : '') + (spec.base ? ' · ' + spec.base : ''));\n"
"        info.id = input.id + '-info';\n"
"        input.setAttribute('aria-describedby', info.id);\n"
"        restore.type = 'button'; restore.className = 'secondary';\n"
"        restore.setAttribute('aria-label', 'Gyári cím visszaállítása – ' + spec.label);\n"
"        input.oninput = () => {\n"
"            if (input.valueAsNumber === spec.address) draft.delete(spec.id);\n"
"            else draft.set(spec.id, input.value);\n"
"            status();\n"
"        };\n"
"        restore.onclick = () => { input.value = spec.address; input.oninput(); input.focus(); };\n"
"        description.append(label, info);\n"
"        box.append(description, input, restore);\n"
"        get('register-rows').append(box);\n"
"        return {spec, input, restore, box};\n"
"    }\n"
"    function validSchema(list) {\n"
"        if (!Array.isArray(list) || !list.length) return false;\n"
"        const ids = new Set();\n"
"        return list.every(spec => {\n"
"            if (!spec || typeof spec.id !== 'string' || !spec.id || ids.has(spec.id) ||\n"
"                typeof spec.label !== 'string' || !spec.label || ![3, 4].includes(spec.function) ||\n"
"                !Number.isInteger(spec.words) || spec.words < 1 || spec.words > 125 ||\n"
"                !Number.isInteger(spec.address) || spec.address < 0 || spec.address > 65536 - spec.words)\n"
"                return false;\n"
"            ids.add(spec.id);\n"
"            return true;\n"
"        });\n"
"    }\n"
"    async function select(id) {\n"
"        const token = ++generation;\n"
"        selected = id;\n"
"        rows = [];\n"
"        const modbus = profiles[id]?.unit != null;\n"
"        ready = !modbus;\n"
"        get('registers').hidden = !modbus;\n"
"        get('register-rows').replaceChildren();\n"
"        get('register-retry').hidden = true;\n"
"        get('register-status').textContent = modbus ? 'Gyári regisztercímek betöltése…' : '';\n"
"        updateSaveButton();\n"
"        if (!modbus) return;\n"
"        try {\n"
"            const reply = await apiFetch('/api/inverter/registers?profile=' + encodeURIComponent(id), {cache: 'no-store'});\n"
"            if (!reply.ok) throw Error('HTTP ' + reply.status);\n"
"            const {registers} = await reply.json();\n"
"            if (token !== generation) return;\n"
"            if (!validSchema(registers)) throw Error('Érvénytelen regiszterlista.');\n"
"            if (!drafts.has(id)) drafts.set(id, new Map(Object.entries(savedOverrides())));\n"
"            const draft = drafts.get(id);\n"
"            rows = registers.map(spec => row(spec, draft));\n"
"            ready = true;\n"
"            status();\n"
"        } catch (error) {\n"
"            if (token !== generation) return;\n"
"            get('register-status').textContent = 'Nem sikerült betölteni a gyári regisztercímeket. ' + error.message;\n"
"            const retry = get('register-retry');\n"
"            retry.hidden = false;\n"
"            retry.onclick = () => select(id);\n"
"        } finally { if (token === generation) updateSaveButton(); }\n"
"    }\n"
"    function values() {\n"
"        const result = {}, previous = savedOverrides();\n"
"        for (const {spec, input} of rows) {\n"
"            // A rejtett változat mentett címét egy másik modell mentése ne módosítsa.\n"
"            const value = applicable(spec) ? input.valueAsNumber : (previous[spec.id] ?\? spec.address);\n"
"            if (value !== spec.address) result[spec.id] = value;\n"
"        }\n"
"        return result;\n"
"    }\n"
"    return {select, reset: () => drafts.clear(), isReady: () => ready, variantChanged: () => { if (ready) status(); }, values};\n"
"})();\n"
"</script><script>'use strict';\n"
"const get = id => document.getElementById(id);\n"
"const apiFetch = (url, options) => fetch(url, options);\n"
"const serial = 'Inverter sorozatszáma';\n"
"const pem = 'Megbízható helyi CA tanúsítványa (PEM, opcionális)';\n"
"const hostLabel = 'Inverter, adatgyűjtő vagy átjáró IP-címe / gépneve';\n"
"const cloudHost = 'A szolgáltató API-gépneve';\n"
"const profiles = {\n"
"    huawei_modbus: {name: 'Huawei SUN2000 L1/M1 · Modbus TCP', unit: 1},\n"
"    goodwe_modbus: {name: 'GoodWe ET/EH · Modbus TCP', unit: 247},\n"
"    sungrow_modbus: {name: 'Sungrow SH · Modbus TCP', unit: 1},\n"
"    solax_modbus: {name: 'SolaX X1/X3 G4 · Modbus TCP', unit: 1},\n"
"    victron_modbus: {name: 'Victron GX · Modbus TCP', unit: 100},\n"
"    solaredge_modbus: {name: 'SolarEdge SunSpec · Modbus TCP', port: 1502, unit: 1},\n"
"    deye_modbus: {name: 'Deye SG04LP3 · Modbus TCP átjáró', unit: 1},\n"
"    deye_rtu: {name: 'Deye SG04LP3 · általános RTU-over-TCP átjáró', port: 8899, unit: 1},\n"
"    deye_lse3: {name: 'Deye SG04LP3 · SOLARMAN LSE-3 RAW adatgyűjtő', port: 8899, unit: 1},\n"
"    deye_v5: {name: 'Deye SG04LP3 · SOLARMAN V5', port: 8899, unit: 1, device: 'Adatgyűjtő sorozatszáma (decimális)'},\n"
"    solplanet_modbus: {name: 'Solplanet ASW8000-T (ASW-T) · Modbus TCP átjáró', unit: 3},\n"
"    fronius_http: {name: 'Fronius · helyi Solar API', port: 80, device: 'Inverterazonosító az akkutöltöttséghez (több inverter esetén)'},\n"
"    solax_http: {name: 'SolaX Pocket · helyi HTTP', port: 80, secret: 'Pocket helyi jelszó'},\n"
"    solplanet_http: {name: 'Solplanet ASW8000-T · helyi HTTP', port: 8484, device: serial},\n"
"    solplanet_https: {name: 'Solplanet ASW8000-T · helyi HTTPS', port: 443, device: serial, trustedPem: pem},\n"
"    victron_mqtt: {name: 'Victron GX · helyi MQTT', port: 1883, device: 'VRM Portal ID (12 hexadecimális karakter)',\n"
"        user: 'MQTT-felhasználónév (opcionális)', secret: 'MQTT-jelszó (opcionális)', trustedPem: pem},\n"
"    fronius_cloud: {name: 'Fronius Solar.web Query API', port: 443, host: 'api.solarweb.com', interval: 5,\n"
"        device: 'PV-rendszer azonosítója (UUID)', key: 'AccessKeyId', secret: 'AccessKeyValue'},\n"
"    huawei_cloud: {name: 'Huawei FusionSolar Northbound API', port: 443, host: 'eu5.fusionsolar.huawei.com', interval: 60,\n"
"        device: serial, user: 'Northbound API-felhasználó', secret: 'Rendszerkód (systemCode)'},\n"
"    solax_cloud: {name: 'SolaXCloud v2', port: 443, host: 'global.solaxcloud.com', interval: 5,\n"
"        device: 'Wi-Fi modul sorozatszáma (Wi-Fi SN)', secret: 'API-token (tokenId)'},\n"
"    solplanet_cloud: {name: 'Solplanet ASW8000-T · AISWEI Cloud', port: 443, host: 'eu-api-genergal.aisweicloud.com', interval: 20,\n"
"        user: 'Fiók AppKey', secret: 'Fiók AppSecret', key: 'Erőmű API-kulcsa (Plant API Key)'}\n"
"};\n"
"const weekdays = ['Hétfő', 'Kedd', 'Szerda', 'Csütörtök', 'Péntek', 'Szombat', 'Vasárnap'];\n"
"let saved, master, loading = false, saving = false;\n"
"const overrides = new Map();\n"
"\n"
"function el(tag, text) {\n"
"    const node = document.createElement(tag);\n"
"    if (text != null) node.textContent = text;\n"
"    return node;\n"
"}\n"
"function field(target, title, type, value, attrs = {}) {\n"
"    const label = el('label', title);\n"
"    const input = el(type === 'textarea' ? type : 'input');\n"
"    if (type !== 'textarea') input.type = type;\n"
"    Object.assign(input, attrs);\n"
"    if (type === 'checkbox') input.checked = !!value;\n"
"    else input.value = value ?\? '';\n"
"    label.append(input);\n"
"    target.append(label);\n"
"    return input;\n"
"}\n"
"function endpointUnchanged() {\n"
"    if (!saved || !saved.profile || get('profile').value !== saved.profile) return false;\n"
"    return ['host', 'port', 'unit', 'device', 'user'].every(key => {\n"
"        const input = get(key);\n"
"        return !input || String(saved[key] ?\? '') === input.value.trim();\n"
"    });\n"
"}\n"
"function updateEndpointFields() {\n"
"    const same = endpointUnchanged();\n"
"    const octets = (get('host')?.value.trim() || '').split('.');\n"
"    const numericLan = octets.length === 4 && octets.every(octet =>\n"
"        /^(0|[1-9][0-9]{0,2})$/.test(octet) && Number(octet) <= 255);\n"
"    const rebind = same && numericLan && !profiles[saved.profile]?.interval;\n"
"    get('rebind-control').hidden = !rebind;\n"
"    if (!rebind) get('rebind-device').checked = false;\n"
"    for (const [key, flag] of [['secret', 'hasSecret'], ['key', 'hasKey']]) {\n"
"        const input = get(key);\n"
"        if (!input) continue;\n"
"        const keep = same && saved[flag];\n"
"        input.required = !keep && get('profile').value !== 'victron_mqtt';\n"
"        input.placeholder = keep ? 'Mentett érték megtartása' : '';\n"
"    }\n"
"}\n"
"function updateSaveButton() {\n"
"    get('inverter-fields').disabled = saving;\n"
"    get('inverter-form').setAttribute('aria-busy', String(saving));\n"
"    get('save-inverter').disabled = saving || !saved || !inverterRegisters.isReady();\n"
"}\n"
"function showProfile(initial) {\n"
"    const id = get('profile').value, profile = profiles[id];\n"
"    inverterRegisters.select(id);\n"
"    const grid = get('connection');\n"
"    grid.replaceChildren();\n"
"    get('transport-help').textContent = '';\n"
"    get('rebind-control').hidden = true;\n"
"    get('rebind-device').checked = false;\n"
"    if (!profile) return;\n"
"    const cfg = initial ? saved : {};\n"
"    const hint = profile.interval ? 'Felhős lekérdezés ' + profile.interval + ' percenként. A szolgáltatói mérés kora az oldal tetején látható.' :\n"
"        'Helyi adatfrissítés 5 másodpercenként.';\n"
"    get('transport-help').textContent = hint + (profile.trustedPem ? ' TLS-nél a megadott gépnévnek szerepelnie kell a tanúsítványban.' : '') +\n"
"        (id === 'victron_mqtt' ? ' A 8883-as port vagy helyi CA megadása TLS-t kapcsol.' : '') +\n"
"        (id === 'solax_http' ? ' A Pocket helyi HTTP-kapcsolata titkosítás nélkül küldi a jelszót.' : '');\n"
"    field(grid, profile.host ? cloudHost : hostLabel, 'text', cfg.host ?\? profile.host,\n"
"        {id: 'host', required: true, maxLength: 127, pattern: '[a-zA-Z0-9.\\\\-]+', oninput: updateEndpointFields});\n"
"    field(grid, 'Port', 'number', cfg.port ?\? profile.port ?\? 502, {id: 'port', min: 1, max: 65535,\n"
"        step: 1, required: true, oninput: updateEndpointFields});\n"
"    if (profile.unit != null) field(grid, 'Modbus eszközcím (Unit ID)', 'number', cfg.unit ?\? profile.unit,\n"
"        {id: 'unit', min: 0, max: 255, step: 1, required: true, oninput: updateEndpointFields});\n"
"    if (id === 'solax_modbus') {\n"
"        const label = el('label', 'Inverter kivitele'), model = el('select');\n"
"        model.id = 'device';\n"
"        model.onchange = () => {\n"
"            updateEndpointFields();\n"
"            inverterRegisters.variantChanged();\n"
"        };\n"
"        for (const [value, title] of [['', 'X3-G4 (háromfázisú)'], ['X1-G4', 'X1-G4 (egyfázisú)'],\n"
"                ['X3-G4-PRO', 'X3-HYB-G4 PRO (háromfázisú)']]) {\n"
"            const option = el('option', title); option.value = value; model.append(option);\n"
"        }\n"
"        model.value = /^x1/i.test(cfg.device || '') ? 'X1-G4' : cfg.device === 'X3-G4-PRO' ? 'X3-G4-PRO' : '';\n"
"        label.append(model); grid.append(label);\n"
"    }\n"
"    for (const key of ['device', 'user', 'key', 'secret', 'trustedPem']) {\n"
"        if (!profile[key]) continue;\n"
"        const hidden = key === 'secret' || key === 'key', cert = key === 'trustedPem';\n"
"        const input = field(grid, profile[key], hidden ? 'password' : cert ? 'textarea' : 'text', hidden ? '' : cfg[key],\n"
"            {id: key, maxLength: cert ? 3071 : hidden ? 159 : 95, autocomplete: hidden ? 'new-password' : 'off',\n"
"                required: !cert && !(key === 'user' && id === 'victron_mqtt') && !(key === 'device' && id === 'fronius_http'), oninput: updateEndpointFields});\n"
"        if (cert) input.rows = 5;\n"
"        if (key === 'device' && id === 'fronius_http') input.pattern = '[0-9]+';\n"
"        if (key === 'device' && id === 'deye_v5') input.pattern = '[0-9]{1,10}';\n"
"        if (key === 'device' && id === 'victron_mqtt') input.pattern = '[a-fA-F0-9]{12}';\n"
"    }\n"
"    updateEndpointFields();\n"
"}\n"
"function clock(minutes) {\n"
"    return String(Math.floor(minutes / 60)).padStart(2, '0') + ':' + String(minutes % 60).padStart(2, '0');\n"
"}\n"
"function minutes(clockTime) {\n"
"    const [hours, mins] = clockTime.split(':').map(Number);\n"
"    return hours * 60 + mins;\n"
"}\n"
"function programEditor(target, source) {\n"
"    const program = el('div');\n"
"    target.append(program);\n"
"    const rows = weekdays.map((day, i) => {\n"
"        const time = source?.days?.[i];\n"
"        const row = el('div'); row.className = 'week-row';\n"
"        const enabled = field(row, day, 'checkbox', time?.enabled);\n"
"        const start = field(row, 'Kezdet', 'time', clock(time?.start ?\? 1320), {required: true});\n"
"        const end = field(row, 'Vége', 'time', clock(time?.end ?\? 360), {required: true});\n"
"        enabled.onchange = () => { start.disabled = end.disabled = !enabled.checked; };\n"
"        enabled.onchange(); program.append(row);\n"
"        return {enabled, start, end};\n"
"    });\n"
"    const wake = field(program, 'Érintés utáni ébrenlét (másodperc)', 'number', source?.touchWakeSeconds || 30,\n"
"        {required: true, min: 1, max: 3600, step: 1});\n"
"    return {node: program, value: () => ({days: rows.map(({enabled, start, end}) =>\n"
"        ({enabled: enabled.checked, start: minutes(start.value), end: minutes(end.value)})), touchWakeSeconds: Number(wake.value)})};\n"
"}\n"
"function peerPrograms(peers) {\n"
"    const ids = new Map(Object.keys(saved.slaveSchedules || {}).map(id => [id, id]));\n"
"    for (const peer of peers) ids.set(peer.id, peer.name);\n"
"    for (const [id, name] of ids) {\n"
"        if (overrides.has(id)) { overrides.get(id).legend.textContent = name + ' · időprogram'; continue; }\n"
"        const box = el('fieldset'), legend = el('legend', name + ' · időprogram');\n"
"        box.append(legend);\n"
"        const previous = saved.slaveSchedules?.[id];\n"
"        const own = field(box, 'Saját időprogram és ébresztési idő használata', 'checkbox', !!previous);\n"
"        // Az örökölt program szerkesztése a Master aktuális űrlapértékeiből indul.\n"
"        const entry = {own, legend, editor: null};\n"
"        own.onchange = () => {\n"
"            if (own.checked && !entry.editor) entry.editor = programEditor(box, previous || master.value());\n"
"            if (entry.editor) {\n"
"                entry.editor.node.hidden = !own.checked;\n"
"                entry.editor.node.querySelectorAll('input').forEach(input => {\n"
"                    if (!own.checked) input.disabled = true;\n"
"                    else if (input.type !== 'time') input.disabled = false;\n"
"                });\n"
"                if (own.checked) entry.editor.node.querySelectorAll('input[type=checkbox]').forEach(input => input.onchange());\n"
"            }\n"
"        };\n"
"        own.onchange();\n"
"        overrides.set(id, entry);\n"
"        get('slave-programs').append(box);\n"
"    }\n"
"}\n"
"async function readSettings() {\n"
"    const response = await apiFetch('/api/inverter', {cache: 'no-store'});\n"
"    if (!response.ok) throw Error(await response.text());\n"
"    return response.json();\n"
"}\n"
"function syncStatus(data) {\n"
"    const age = data.measurementAgeSeconds;\n"
"    const ageText = Number.isFinite(age) ? (age < 60 ? age + ' mp' : Math.floor(age / 60) + ' perc') : 'ismeretlen';\n"
"    const status = [data.syncStatus];\n"
"    if (data.profile) status.push('Mérés kora: ' + ageText);\n"
"    if (data.activeIpv4) status.push('Aktuális helyi IP-cím: ' + data.activeIpv4);\n"
"    get('sync-status').textContent = status.filter(Boolean).join(' · ');\n"
"}\n"
"function fill(data) {\n"
"    saved = data;\n"
"    inverterRegisters.reset();\n"
"    get('profile').value = data.profile || '';\n"
"    showProfile(true);\n"
"    get('battery').checked = !!data.battery;\n"
"    get('latitude').value = data.latitude ?\? '';\n"
"    get('longitude').value = data.longitude ?\? '';\n"
"    get('master-program').replaceChildren();\n"
"    master = programEditor(get('master-program'), data.schedule);\n"
"    overrides.clear(); get('slave-programs').replaceChildren(); peerPrograms([]);\n"
"    updateSaveButton();\n"
"    syncStatus(data);\n"
"}\n"
"function values() {\n"
"    const id = get('profile').value;\n"
"    const data = {profile: id, host: get('host').value.trim(), port: Number(get('port').value),\n"
"        unit: Number(get('unit')?.value ?\? 0), battery: get('battery').checked,\n"
"        latitude: Number(get('latitude').value), longitude: Number(get('longitude').value),\n"
"        schedule: master.value(), slaveSchedules: {}};\n"
"    if (profiles[id]?.unit != null) data.registerOverrides = inverterRegisters.values();\n"
"    if (saved.revision != null) data.revision = saved.revision;\n"
"    if (!get('rebind-control').hidden && get('rebind-device').checked) data.rebindDevice = true;\n"
"    for (const key of ['device', 'user', 'secret', 'key', 'trustedPem']) {\n"
"        const input = get(key);\n"
"        if (input && input.value) data[key] = (key === 'key' || key === 'secret') ? input.value : input.value.trim();\n"
"    }\n"
"    for (const [id, entry] of overrides) if (entry.own.checked) data.slaveSchedules[id] = entry.editor.value();\n"
"    return data;\n"
"}\n"
"async function refresh() {\n"
"    if (loading || saving || document.hidden) return;\n"
"    loading = true;\n"
"    try {\n"
"        const data = await readSettings();\n"
"        if (!saved) fill(data); else syncStatus(data);\n"
"        peerPrograms(await LoxoneSlaves.refresh());\n"
"    } catch (error) {\n"
"        get('sync-status').textContent = 'A kijelző nem olvasható. ' + error.message;\n"
"    } finally { loading = false; }\n"
"}\n"
"for (const [id, profile] of Object.entries(profiles)) {\n"
"    const option = el('option', profile.name); option.value = id; get('profile').append(option);\n"
"}\n"
"get('profile').onchange = () => showProfile(get('profile').value === saved?.profile);\n"
"get('inverter-form').onsubmit = async event => {\n"
"    event.preventDefault();\n"
"    if (saving || !saved || !inverterRegisters.isReady() || !get('inverter-form').reportValidity()) return;\n"
"    const data = values();\n"
"    if (data.profile === 'deye_v5' && (!Number(data.device) || Number(data.device) > 4294967295)) {\n"
"        get('result').textContent = 'Az adatgyűjtő sorozatszáma 1 és 4294967295 közötti egész szám lehet.'; return;\n"
"    }\n"
"    get('rebind-device').checked = false;\n"
"    saving = true; updateSaveButton();\n"
"    get('result').textContent = 'Mentés folyamatban…';\n"
"    try {\n"
"        const response = await apiFetch('/api/inverter', {method: 'POST', headers: {'Content-Type': 'application/json',\n"
"            'X-Zolee-Inverter': '1'}, body: JSON.stringify(data)});\n"
"        if (!response.ok) throw Error(await response.text());\n"
"        for (const key of ['secret', 'key']) if (get(key)) get(key).value = '';\n"
"        fill(await readSettings());\n"
"        peerPrograms(await LoxoneSlaves.refresh());\n"
"        get('result').textContent = 'Mentve. A kijelző szinkronizálja az adatokat.';\n"
"    } catch (error) {\n"
"        get('result').textContent = 'A mentés nem igazolt. ' + error.message;\n"
"    } finally { saving = false; updateSaveButton(); }\n"
"};\n"
"refresh();\n"
"setInterval(refresh, 15000);\n"
"</script></body></html>\n";
